LCS — Code
def lcs(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1      # characters match!
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])  # take the best

    return dp[m][n]

print(lcs("ABCBDAB", "BDCABA"))  # → 4
print(lcs("AGGTAB",  "GXTXAYB")) # → 4
Time: O(m × n)
Space: O(m × n) (reducible to O(min(m,n)) with a rolling array)

Rabin-Karp: Full Picture
def rabin_karp(T, P, b=256, q=101):
    n, m = len(T), len(P)
    h_P = hash_str(P, b, q)
    h_W = hash_str(T[:m], b, q)
    matches = []

    for i in range(n - m + 1):
        if h_W == h_P:
            if T[i:i+m] == P:    # verify (avoid false positives)
                matches.append(i)
        if i &lt; n - m:
            # roll the hash
            h_W = (b * (h_W - ord(T[i]) * pow(b, m-1, q)) + ord(T[i+m])) % q

    return matches

Expected time: O(n + m) — one pass, O(1) per step, rare verifications.
False positives (hash collision, no match): re-reduced by choosing large prime \(q\).
